def hook(ctx, nb):
    predicates = ctx.get('predicates', {})
    state = ctx.get('state', {})
    if predicates.get('syntax_error', False) or predicates.get('unknown_column_error', False):
        nb['need_schema_probe'] = True
    if predicates.get('last_result_empty', False):
        nb['fixing_empty_result'] = True
    task = ctx.get('task', {})
    if task.get('task_type') == 'mutation' or predicates.get('mutation_task', False):
        if not state.get('mutation_attempted', False):
            nb['mutation_needs_execution'] = True
            nb['mutation_needs_verification'] = False
        else:
            nb['mutation_needs_execution'] = False
            nb['mutation_needs_verification'] = True
    return None

def hook(ctx, nb):
    if nb.get('need_schema_probe', False):
        nb['need_schema_probe'] = False
        return {'message': 'Schema error detected. Run SHOW TABLES to find exact table names, then DESCRIBE `table_name` to see column names. Wrap names with spaces in backticks.'}
    if nb.get('fixing_empty_result', False):
        nb['fixing_empty_result'] = False
        return {'message': 'Empty result may indicate wrong table/column names or overly strict conditions. Try DESCRIBE to verify schema, or relax WHERE conditions and check sample rows.'}
    if nb.get('mutation_needs_verification', False):
        nb['mutation_needs_verification'] = False
        return {'message': 'After INSERT/UPDATE/DELETE, run a SELECT query to verify the mutation was applied before committing your final answer.'}
    return None

